package ultra.downloads;
import android.app.*;import android.content.*;import android.database.*;import android.net.Uri;import android.provider.MediaStore;import java.util.*;import java.io.*;import java.lang.reflect.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowContentResolver;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33)
public class DL24PerformanceTest {
 Activity c;static int rows=60;
 public static class AudioProvider extends ContentProvider {
 public boolean onCreate(){return true;} public String getType(Uri u){return "audio/mpeg";}public Uri insert(Uri u,ContentValues v){return null;}public int delete(Uri u,String s,String[] a){return 0;}public int update(Uri u,ContentValues v,String s,String[] a){return 0;}
 public Cursor query(Uri u,String[] projection,String selection,String[] args,String sort){MatrixCursor m=new MatrixCursor(new String[]{"_id","_display_name","title","artist","album","_size","mime_type","duration"});for(int n=0;n<rows;n++)m.addRow(new Object[]{n+1,"Track "+n+" ["+id(n)+"].mp3","Track "+n,"Singer "+n,"Album "+n%10,1000,"audio/mpeg",100000});return m;}
 }
 static String id(int n){return String.format(java.util.Locale.US,"T%010d",n);}
 @Before public void setup()throws Exception{c=Robolectric.buildActivity(Activity.class).setup().get();app.revanced.extension.shared.utils.Utils.testContext=c;Shadows.shadowOf(c).grantPermissions(android.Manifest.permission.READ_MEDIA_AUDIO);Library.prefs(c).edit().clear().commit();PlaylistIndex.invalidateCache();Library.wiping=false;Field f=Library.class.getDeclaredField("items");f.setAccessible(true);f.set(null,null);new File(c.getFilesDir(),"ultra_downloads_v1.json").delete();AudioProvider p=new AudioProvider();p.attachInfo(c,null);ShadowContentResolver.registerProviderInternal("media",p);}
 @Test public void scansSixtyAndFourHundredWithPersistentWarmCache()throws Exception{for(int n:new int[]{60,400}){rows=n;/* Independent 60/400 fixtures, not online edits to a detached copy. */Library.prefs(c).edit().remove(LocalPlaylistCopies.PREF).commit();PlaylistIndex.invalidateCache();ArrayList<Catalog.Track> tracks=new ArrayList<>();for(int x=0;x<n;x++)tracks.add(new Catalog.Track(id(x),"Track "+x,"Singer "+x,"Album "+x%10));PlaylistIndex.roster(c,Arrays.asList(new Catalog.Playlist("VLPLbench","Bench","")));PlaylistIndex.record("PLbench",tracks,true);long s=System.nanoTime();int changed=LocalAudio.scan(c);long cold=System.nanoTime()-s;assertEquals(n,Library.all(c).size());assertTrue(changed>0);s=System.nanoTime();assertEquals(0,LocalAudio.scan(c));long warm=System.nanoTime()-s;assertArrayEquals(new int[]{n,0},LocalAudio.membership(c,Library.all(c)));System.out.println("DL24_SCAN rows="+n+" cold_ms="+cold/1000000+" warm_ms="+warm/1000000);Field f=Library.class.getDeclaredField("items");f.setAccessible(true);f.set(null,null);assertEquals(0,LocalAudio.scan(c));assertEquals(n,Library.all(c).size());}}
 @Test public void indexMatchesLegacyIncludingAmbiguityAndVersions(){List<Catalog.Track> tracks=Arrays.asList(new Catalog.Track("aaaaaaaaaa1","Pal","KK",""),new Catalog.Track("bbbbbbbbbb2","Pal","Arijit Singh",""),new Catalog.Track("cccccccccc3","Kesariya (Official Video)","Arijit Singh - Topic",""));AudioMatchIndex index=new AudioMatchIndex(tracks);for(String file:new String[]{"Pal.mp3","KK - Pal.mp3","Pal remix.mp3","Kesariya.mp3","random.mp3","Pal [aaaaaaaaaa1] (1).mp3"})for(String title:new String[]{"","Pal","Pal (Remix)","Kesariya"})for(String who:new String[]{"","KK","Arijit Singh","Various Artists"})assertEquals(file+title+who,LocalAudio.match(file,title,who,tracks),index.match(file,title,who));}
 @Test public void indexedMatcherBenchmarks60And400(){for(int n:new int[]{60,400}){ArrayList<Catalog.Track> tracks=new ArrayList<>();for(int k=0;k<n;k++)tracks.add(new Catalog.Track(id(k),"Melody "+k,"Singer "+k,""));long s=System.nanoTime();for(Catalog.Track t:tracks)assertEquals(t.id,LocalAudio.match(t.artist+" - "+t.title+".mp3","","",tracks));long legacy=System.nanoTime()-s;s=System.nanoTime();AudioMatchIndex index=new AudioMatchIndex(tracks);for(Catalog.Track t:tracks)assertEquals(t.id,index.match(t.artist+" - "+t.title+".mp3","",""));long fast=System.nanoTime()-s;System.out.println("DL24_MATCH rows="+n+" legacy_ms="+legacy/1000000+" indexed_ms="+fast/1000000);}}
 @Test public void batchImportPreservesHiddenAndProtectsDownloads()throws Exception{Library.Item original=Library.add(c,id(0),"Download");original.uri="content://protected";original.state="done";Library.Item bad=new Library.Item();bad.id=id(0);bad.imported=true;bad.uri="content://new";assertEquals(0,Library.applyImports(c,Arrays.asList(bad)));assertSame(original,Library.get(c,id(0)));Library.Item old=new Library.Item();old.id=id(1);old.uri="content://local";old.imported=true;old.hidden=true;Library.applyImports(c,Arrays.asList(old));Library.Item next=new Library.Item();next.id=id(2);next.uri=old.uri;next.imported=true;Library.applyImports(c,Arrays.asList(next));assertNull(Library.get(c,id(1)));assertTrue(Library.get(c,id(2)).hidden);}
}
